style.css:
@-moz-document domain("youtube.com") {
/* GLOW RIOT - CHANNEL NAMES */

yt-lockup-view-model a[href^="/@"],
yt-lockup-view-model a[href^="/channel/"],
yt-lockup-view-model .ytAttributedStringLink {
  color: #ff4dcc !important;
  -webkit-text-fill-color: #ff4dcc !important;
  text-shadow: 0 0 6px #ff1493 !important;
}

/* GLOW RIOT - VIEWS AND UPLOAD DATES */

yt-lockup-view-model .ytContentMetadataViewModelMetadataText,
yt-lockup-view-model .yt-content-metadata-view-model__metadata-text {
  color: #d98aff !important;
  -webkit-text-fill-color: #d98aff !important;
  text-shadow: 0 0 4px rgba(204, 102, 255, 0.5) !important;
}
}
